INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62394038', 62394038, 'analyze_legacy', 'Kab. Blitar', 'kabkota', 'RSUD Ngudi Waluyo Wlingi', 'BELANJA JASA PENGOLAHAN SAMPAH', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Blitar (Kab.)', 895000000, 'December 2025', 'BLUD', 1, 1, '1 TAHUN', 'BELANJA JASA PENGOLAHAN SAMPAH', 'I. JENIS PEKERJAAN ( Spesifikasi minimal yang diminta ) 1. Jenis Limbah yang diangkut a. Limbah medis infeksius b. Limbah Produk Farmasi c. Limbah bahan Kimia kadaluarsa d. Limbah kemasan produk farmasi e. Sludge IPAL f. Minyak pelumas bekas g. Kain majun bekas h. Aki/baterai bekas i. Limbah elektronik / Lampu TL j. Kemasan bekas tinta k. Toner bekas l. Limbah sitotostika 2. Pengangkutan Limbah B3 a. Pengangkutan Limbah B3 harus dilengkapi dengan SPO dan dapat dilakukan pemutakhiran secara berkala dan berkesinambungan b. Petugas mengangkut limbah dengan menggunakan Alat Pelindung Diri c. Pengangkutan Limbah B3 harus dilengkapi dengan perjanjian kerja sama secara three parted yang ditandatangani oleh pimpinan dari pihak Fasllitas Pelayanan Kesehatan, pihak pengangkut Limbah B3, dan pengolah atau penimbun limbah B3. d. Pihak pengangkut dan pengolah atau penimbun Limbah B3 memiliki perizinan yang lengkap sesuai dengan ketentuan peraturan perundang-undangan. Izin yang dimiliki oleh pengolah maupun pengangkut harus sesual dengan jenis limbah yang dapat diolah/ diangkut, e. Jenis kendaraan dan nomor polisi kendaraan pengangkut Limbah B3 yang digunakan pihak pengangkut limbah B3 harus sesuai dengan yang tercantum dalam perizinan pengangkutan Limbah B3 yang dimiliki f. Setiap pengiriman Limbah B3 dari Fastilitas Pelayanan Kesehatan ke pihak pengolah atau penimbun harus disertakan manifest Limbah B3 yang ditandatangani dan stempel oleh pihak Fasilitas Pelayanan Kesehatan, pihak pengangkut dan pihak pengolah/ penimbun limbah B3 dan di arsip oleh pihak Fasllitas Pelayanan Kesehatan, atau mengisi sistem pencatatan elektronik dari KLHK. g. Ditetapkan jadwal tetap pengangkutan limbah B3 oleh pihak pengangkut Limbah B3 h. Kendaraan angkut limbah B3 yang digunakan layak pakai, dilengkapi simbol limbah B3 dan nama pihak pengangkut Limbah B3 serta ada fasilitas pendingin. i. Memiliki armada yang dilengkapi dengan GPS tracking untuk memudahkan dalam melakukan mengawasan pengangkutan limbah II. JADWAL, HARI DAN JAM KERJA 1. Waktu Pelaksanaan pengangkutan limbah dilakukan setiap 2 ( dua ) hari sekali 2. Untuk tanggal merah atau hari libur pengangkutan limbah tetap dilakukan III. TANGGUNG JAWAB PENYEDIA JASA Tanggung Jawab Penyedia/ pengelola jasa pengolahan limbah secara umum : a. Bertanggung jawab menjamin surat legalitas yang dimiliki sesuai dengan sebenarnya sesuai dengan ijin yang dikeluarkan kementrian lingkungan hidup dan kehutanan republik Indonesia b. Bertanggungjawab atas keamanan, kualitas dan kuantitas pengelolaan dan pengangkutan sampah medis yang diambil c. Berkewajiban menerima jenis limbah B3 sesuai dengan perjanjian kerjasama d. Menerbitkan sertifikat limbah B3 dan berita acara penerimaan limbah B3 e. Menyediakan safety box dan kantong sampah kuning infeksius f. Menyediakan atau meminjami whilebin atau depo tempat sampah infeksius g. Memiliki akun aplikasi SIRAJA untuk melakukan pelaporan limbah secara elektronik untuk dapat menerbitkan manifestronik dari KLHK h. Membantu pembuatan dan pelatihan manifest elektronik', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 454452);
