INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65860059', 65860059, 'analyze_legacy', 'Kota Batu', 'kabkota', 'Puskesmas Batu', 'Belanja Bahan-Bahan Kimia - Paket Kimia Klinik', 'Barang', 'E-Purchasing', 'Jawa Timur, Batu (Kota)', 18581500, 'February 2026', 'BLUD', 1, 1, '1 Paket', 'GOT (AST) GPT (ALT) Reagen Urid Acid Mono SL Reagent Cholesterol Reagent Glukosa Triglyceride Mono SL', '- GOT (AST) sebanyak 1 botol : reagen untuk mengukur aktivitas enzim AST untuk menilai kerusakan hati atau otot jantung. Kemasan: bentuk cairan siap pakai atau bubuk liofilisasi, biasanya dalam botol. - GPT (ALT) sebanyak 1 botol : reagen untuk mengukur kadar enzim Alanin Aminotransferase dalam darah untuk menilai fungsi hati. Kemasan : bentuk cairan siap pakai atau bubuk liofilisasi, biasanya dalam botol. - Reagen Urid Acid Mono SL sebanyak 1 botol : Metode: Enzimatik (Uricase-Peroksidase). Formulasi: Monoreagen (satu komponen). Sampel: Serum atau Plasma darah (bisa juga urine untuk beberapa merek). Prinsip: Asam urat diubah oleh enzim urikase menjadi alantoin dan hidrogen peroksida (H₂O₂). H₂O₂ kemudian bereaksi dengan reagen kromogenik membentuk produk berwarna yang diukur absorbansinya pada panjang gelombang tertentu (biasanya 500-600 nm) - Reagent Cholesterol sebanyak 1 botol : Metode Enzimatik: Menggunakan enzim seperti kolesterol esterase, kolesterol oksidase, dan peroksidase (misalnya, metode CHOD-PAP) untuk menghasilkan warna yang proporsional dengan kadar kolestero. kemasan bentuk cair siap pakai. Jenis Sampel: Untuk serum atau plasma darah. Keakuratan Tinggi: Didesain untuk presisi dan keandalan diagnosis. Sertifikasi: Memiliki izin edar Kemenkes RI (AKD/AKL) dan sertifikasi mutu seperti ISO 13485:2016. - Reagent Glukosa sebanyak 1 botol : Metode Pengukuran: GOD-PAP (Glucose Oxidase-Peroxidase) atau Heksokinase. Komposisi: Mengandung enzim glukosa oksidase, peroksidase, substrat (glukosa), buffer, dan pewarna (kromogen) untuk reaksi warna. Kemasan botol, Reagen Cair: Siap pakai. Memiliki izin edar Kemenkes RI (AKL/AKD) dan sertifikasi mutu (ISO 13485). - Triglyceride Mono SL sebanyak 1 botol : reagen Pengukuran kadar trigliserida (TG) pada sampel serum atau plasma. Metode: Enzimatik. Tipe Sistem: Open system, artinya bisa digunakan pada berbagai merek alat analyzer kimia klinik (otomatis dan semi-otomatis).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 457566);
